CREATE TYPE "ContentStatus" AS ENUM ('DRAFT', 'PUBLISHED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Article" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "excerpt" TEXT NOT NULL, "content" TEXT NOT NULL, "coverImage" TEXT, "author" TEXT NOT NULL, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "publishedAt" TIMESTAMP(3), "categoryId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Article_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Event" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "description" TEXT NOT NULL, "location" TEXT, "image" TEXT, "registrationUrl" TEXT, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3), "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Event_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BoardMember" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "role" TEXT NOT NULL, "division" TEXT NOT NULL, "bio" TEXT, "photo" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "BoardMember_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GalleryImage" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "category" TEXT, "imagePath" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "GalleryImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrganizationSetting" ("id" TEXT NOT NULL DEFAULT 'main', "name" TEXT NOT NULL DEFAULT 'KSB UB', "shortDescription" TEXT NOT NULL DEFAULT 'Informasi organisasi sedang dilengkapi.', "profile" TEXT NOT NULL DEFAULT 'Profil organisasi sedang dilengkapi.', "history" TEXT NOT NULL DEFAULT 'Sejarah organisasi sedang dilengkapi.', "vision" TEXT NOT NULL DEFAULT 'Visi sedang dilengkapi.', "mission" TEXT NOT NULL DEFAULT 'Misi sedang dilengkapi.', "email" TEXT, "phone" TEXT, "address" TEXT, "instagram" TEXT, "logoPath" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "OrganizationSetting_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name");
CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE UNIQUE INDEX "Article_slug_key" ON "Article"("slug");
CREATE UNIQUE INDEX "Event_slug_key" ON "Event"("slug");
ALTER TABLE "Article" ADD CONSTRAINT "Article_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE;
